pug:
.gray-block
    table.w100
        tr
            td.m-w.pb0(style="vertical-align: top;")
                p.number 2
            td.w-a.pb0(style="vertical-align: middle;")
                p.text {{ text_1 }}
    p.fat-text.pb12.pt24 {{ text_2 }}
    .promo-block
        p.promo-text {{ text_3 }}
    p.small-gray-text.pt6 {{ text_4 }}

styl:
.text { font-family: Helvetica !important;
  font-size: 18px;
  color: #393a44;
  letter-spacing: 0;
  line-height: 26px;
  font-weight: 400; }
.text.bold { font-weight: 700; }
.pb12 { padding-bottom: 12px !important; }
.pt6 { padding-top: 6px; }
.pt24 { padding-top: 24px; }
@media screen and (max-width: 600px) {
  .text.mob-text,
  .grey-text.mob-text { font-size: 17px !important; }
}
.w-a { width: auto !important;
  vertical-align: middle; }
.number { background: #ececed;
  width: 54px;
  max-height: 54px;
  border-radius: 16px;
  font-family: Helvetica !important;
  color: #393a44;
  font-weight: 700;
  font-size: 24px;
  line-height: 24px;
  padding: 15px 0;
  text-align: center; }
.w-a { width: auto !important;
  vertical-align: middle; }
table[class=body] table.column td,
table[class=body] table.columns td.m-w { min-width: 78px !important;
  width: 78px !important; }
.fat-text { font-family: Helvetica !important;
  font-style: normal;
  font-weight: 700;
  font-size: 18px;
  line-height: 20px;
  color: #393a44; }
@media screen and (max-width: 600px) {
  .fat-text { font-size: 16px !important;
    line-height: 18px !important; }
}
.small-gray-text { font-family: Helvetica !important;
  font-style: normal;
  font-weight: 400;
  font-size: 16px;
  line-height: 24px;
  color: #84868b; }
.gray-block { padding: 24px;
  background: #f9f9f9;
  border-radius: 12px; }
.promo-block { background: #ffefe0 url("https://fsms.quadcode.com/storage/public/d5/oe/ha0ggnfnh4cs75u0/ift.png") center right 22px no-repeat;
  background-size: 32px;
  border: 2px dashed #f70;
  border-radius: 16px;
  padding: 16px 22px; }
.promo-text { font-family: Helvetica !important;
  font-style: normal;
  font-weight: 700;
  font-size: 24px;
  line-height: 31px;
  color: #f70;
  word-break: break-word;
  padding-right: 32px; }
@media screen and (max-width: 600px) {
  .promo-text { font-size: 20px !important;
    line-height: 29px !important; }
}
